let raw = '';

try {
  raw = $input.first().json.output[0].content[0].text;
} catch (e) {
  raw = '';
}

if (!raw || typeof raw !== 'string') {
  return [{ json: { error: true, message: 'No text found from Message a Model node', raw_output: JSON.stringify($input.first().json) } }];
}

raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1) {
  return [{ json: { error: true, message: 'Model returned non-JSON output', raw_output: raw } }];
}

raw = raw.slice(firstBrace, lastBrace + 1);

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: true, message: 'JSON parse failed', parse_error: e.message, raw_output: raw } }];
}

const source = $('Get row(s) in sheet').first().json;

const cleanSlug = (data.slug || source.slug || '')
  .toString()
  .trim()
  .toLowerCase()
  .replace(/^\/+|\/+$/g, '')
  .replace(/\s+/g, '-')
  .replace(/[^a-z0-9\/-]+/g, '-')
  .replace(/-+/g, '-');

const pageTitle = data.title || source.page_title || data.seo_title || '';
const focus = data.focus_keyphrase || source.focus_keyword || data.focuskw || data.keyphrase || '';
const city = source.city || '';
const state = source.state || '';
const pageType = source.page_type || '';
const alt = data.image_alt || data.alt_tag || source.alt_text || `${focus} display solution${city ? ' in ' + city : ''}`;
const mediaTitle = data.image_title || `${pageTitle || focus || pageType} Image`.trim();
const mediaDescription = data.image_description || `${alt}. Commercial LED display visual for ${pageTitle || focus || pageType}${city || state ? ' serving ' + [city, state].filter(Boolean).join(', ') : ''}.`;

return [{
  json: {
    source_mode: source.source_mode || 'sheet',
    job_id: source.job_id || '',
    callback_url: source.callback_url || '',
    publishing_mode: source.publishing_mode === 'publish' ? 'publish' : 'draft',
    additional_instructions: source.additional_instructions || '',
    page_type: pageType,
    state,
    city,
    post_title: pageTitle,
    page_title: pageTitle,
    seo_title: data.seo_title || pageTitle || '',
    h1: data.h1 || source.h1 || pageTitle || '',
    slug: cleanSlug,
    meta_description: data.meta_description || data.metadesc || data.description || '',
    focus_keyphrase: focus,
    alt_tag: alt,
    media_title: mediaTitle,
    media_description: mediaDescription,
    image_prompt: data.image_prompt || source.image_prompt || data.prompt || '',
    article_html: data.content || data.article_html || source.body_html || data.html || '',
    excerpt: data.excerpt || data.meta_description || '',
    internal_links: source.internal_links || '',
    source_row_number: source.row_number || '',
    source_status: source.status || ''
  }
}];

const item = $input.first().json;

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeText(value) {
  return String(value || '')
    .trim()
    .toLowerCase();
}

const isGlw = String(item.source_mode || '').toLowerCase() === 'glw';

/*
 * Canonical WordPress product mappings.
 */
const productMap = {
  'led video walls': 'direct-view-led-video-walls',
  'direct view led video walls': 'direct-view-led-video-walls',
  'direct-view led video walls': 'direct-view-led-video-walls',

  'led wall rental': 'direct-view-led-video-walls',
  'led wall rentals': 'direct-view-led-video-walls',
  'led video wall rental': 'direct-view-led-video-walls',
  'led video wall rentals': 'direct-view-led-video-walls',

  'outdoor led displays': 'outdoor-led-displays',
  'church led walls': 'church-led-walls',
  'trade show led displays': 'trade-show-led-displays',
  'transparent led displays': 'transparent-led-displays',
  'creative led displays': 'creative-led-displays',
  'interactive led floors': 'interactive-led-floors',
  'led posters': 'led-posters',
  'custom led displays': 'custom-led-displays',

  'cob all-in-one led displays': 'cob-all-in-one-led-displays',
  'cob all in one led displays': 'cob-all-in-one-led-displays',

  'smd all-in-one led displays': 'smd-all-in-one-led-displays',
  'smd all in one led displays': 'smd-all-in-one-led-displays',

  'exhibition led displays': 'exhibition-led-displays',

  'flexible rollable led displays': 'flexible-rollable-led',
  'flexible and rollable led displays': 'flexible-rollable-led',
  'flexible & rollable led': 'flexible-rollable-led',
  'flexible and rollable led': 'flexible-rollable-led',

  'led fan displays': 'led-fans',
  'led fans': 'led-fans'
};

const slugAliasMap = {
  'led-video-walls': 'direct-view-led-video-walls',
  'direct-view-led-video-walls': 'direct-view-led-video-walls',

  'led-wall-rental': 'direct-view-led-video-walls',
  'led-wall-rentals': 'direct-view-led-video-walls',
  'led-video-wall-rental': 'direct-view-led-video-walls',
  'led-video-wall-rentals': 'direct-view-led-video-walls',

  'outdoor-led-displays': 'outdoor-led-displays',
  'church-led-walls': 'church-led-walls',
  'trade-show-led-displays': 'trade-show-led-displays',
  'transparent-led-displays': 'transparent-led-displays',
  'creative-led-displays': 'creative-led-displays',
  'interactive-led-floors': 'interactive-led-floors',
  'led-posters': 'led-posters',
  'custom-led-displays': 'custom-led-displays',
  'cob-all-in-one-led-displays': 'cob-all-in-one-led-displays',
  'smd-all-in-one-led-displays': 'smd-all-in-one-led-displays',
  'exhibition-led-displays': 'exhibition-led-displays',
  'flexible-rollable-led': 'flexible-rollable-led',
  'led-fans': 'led-fans'
};

/*
 * These are page types, NOT product categories.
 */
const genericPageTypes = new Set([
  'city_service',
  'city-service',
  'city',
  'state',
  'state_service',
  'state-service',
  'service',
  'location',
  'location_service',
  'location-service',
  'page_generation',
  'page-generation'
]);

/*
 * Always trust structured geographic fields.
 */
const stateSlug = slugify(item.state);
const citySlug = slugify(item.city);

/*
 * Try to resolve the canonical product.
 */
const productCandidates = [
  item.product,
  item.product_topic,
  item.productTopic,
  item.service,
  item.service_name,
  item.focus_keyword,
  item.focus_keyphrase
];

const pageTypeValue = normalizeText(item.page_type);

if (
  pageTypeValue &&
  !genericPageTypes.has(pageTypeValue)
) {
  productCandidates.push(item.page_type);
}

let productSlug = '';

for (const candidate of productCandidates) {
  const normalized = normalizeText(candidate);

  if (!normalized) {
    continue;
  }

  if (productMap[normalized]) {
    productSlug = productMap[normalized];
    break;
  }

  const candidateSlug = slugify(candidate);

  if (slugAliasMap[candidateSlug]) {
    productSlug = slugAliasMap[candidateSlug];
    break;
  }
}

/*
 * Existing product_slug fallback.
 */
if (!productSlug) {
  const existingProductSlug = slugify(item.product_slug);

  if (existingProductSlug && slugAliasMap[existingProductSlug]) {
    productSlug = slugAliasMap[existingProductSlug];
  }
}

/*
 * Raw slug fallback.
 *
 * IMPORTANT:
 * We may recover a recognized PRODUCT slug here.
 * We never recover state/city from item.slug.
 */
if (!productSlug) {
  const rawSlug = String(item.slug || '')
    .trim()
    .toLowerCase()
    .replace(/^\/+|\/+$/g, '');

  const parts = rawSlug
    .split('/')
    .map((part) => slugify(part))
    .filter(Boolean);

  for (const part of parts) {
    if (slugAliasMap[part]) {
      productSlug = slugAliasMap[part];
      break;
    }
  }
}

/*
 * LEGACY SHEET MODE
 *
 * Preserve prior behavior for old sheet/schedule rows.
 * Do not allow a legacy test row to break the entire workflow.
 */
if (!isGlw && !productSlug) {
  productSlug = slugify(item.page_type || item.product || '');
}

/*
 * GLW SAFETY GATES
 *
 * GLW is the production page-generation path.
 * It must never invent malformed hierarchy.
 */
if (isGlw && !productSlug) {
  throw new Error(
    [
      'GLW: Unable to resolve canonical product parent.',
      `page_type="${item.page_type || ''}"`,
      `category="${item.category || ''}"`,
      `focus_keyword="${item.focus_keyword || ''}"`,
      `product="${item.product || ''}"`,
      `product_topic="${item.product_topic || item.productTopic || ''}"`
    ].join(' ')
  );
}

if (isGlw && !stateSlug) {
  throw new Error(
    `GLW: Unable to resolve state slug from state="${item.state || ''}".`
  );
}

if (isGlw && !citySlug) {
  throw new Error(
    `GLW: Unable to resolve city slug from city="${item.city || ''}".`
  );
}

/*
 * For legacy sheet rows, preserve safe empty handling.
 */
const finalProductSlug = productSlug || '';
const finalStateSlug = stateSlug || '';
const finalCitySlug = citySlug || '';

const desiredHierarchicalSlug = [
  finalProductSlug,
  finalStateSlug,
  finalCitySlug
]
  .filter(Boolean)
  .join('/');

return [
  {
    json: {
      ...item,

      product_slug: finalProductSlug,
      state_slug: finalStateSlug,
      city_slug: finalCitySlug,

      desired_hierarchical_slug: desiredHierarchicalSlug
    }
  }
];

const response = $input.first().json;
const source = $('Prepare Hierarchy Fields').first().json;

let product = {};

if (Array.isArray(response)) {
  product = response[0] || {};
} else if (Array.isArray(response.data)) {
  product = response.data[0] || {};
} else if (response && response.id) {
  product = response;
}

return [{
  json: {
    ...source,
    product_parent_id: Number(product.id || 0),
    product_parent_found: !!product.id,
    product_parent_link: product.link || '',
    product_parent_title: product.title?.rendered || ''
  }
}];

const response = $input.first().json;
const source = $('Prepare Product Parent').first().json;

let list = [];

if (Array.isArray(response)) {
  list = response;
} else if (Array.isArray(response.body)) {
  list = response.body;
} else if (Array.isArray(response.data)) {
  list = response.data;
} else if (response && response.id) {
  list = [response];
}

const statePage = list.find(p => p && p.id) || {};

return [{
  json: {
    ...source,
    state_parent_id: Number(statePage.id || 0),
    state_parent_found: !!statePage.id,
    needs_state_parent: !statePage.id,
    state_parent_link: statePage.link || '',
    state_parent_slug: statePage.slug || ''
  }
}];

const created = $input.first().json;
const source = $('Prepare Product Parent').first().json;

const stateParentId = Number(created.id || 0);

if (!stateParentId) {
  throw new Error('Missing state parent ID after create attempt.');
}

return [{ json: { ...source, state_parent_id: stateParentId, state_parent_found: true, created_state_parent: true } }];

const item = $input.first().json;

let valid = true;
let errorCode = '';
let errorMessage = '';

if (!item.state_parent_id || Number(item.state_parent_id) <= 0) {
  valid = false;
  errorCode = 'MISSING_STATE_PARENT_ID';
  errorMessage = `Missing state_parent_id. Refusing to publish root-level page. product=${item.product_slug || ''}, state=${item.state_slug || ''}, city=${item.city_slug || ''}`;
} else if (!item.city_slug) {
  valid = false;
  errorCode = 'MISSING_CITY_SLUG';
  errorMessage = 'Missing city_slug. Refusing to publish page.';
}

return [{
  json: {
    ...item,
    valid,
    validation_error_code: errorCode,
    validation_error_message: errorMessage,
    validation_error_node: 'Validate Parent Before Publish'
  }
}];

// Get all rows
const rows = $input.all();

// Find the first Ready row
const ready = rows.find(r => {
  const status = String(r.json.Status || r.json.status || "")
    .trim()
    .toLowerCase();

  return status === "ready";
});

// Nothing ready? Stop workflow.
if (!ready) {
  return [];
}

// Return ONLY one record
return [ready];

const input = $input.first().json;
const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const isGlw = Boolean(
  body.jobId ||
  body.type === 'page_generation' ||
  body.page ||
  body.workflowContext ||
  body.publishingSettings
);

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizePublishingMode(...values) {
  for (const value of values) {
    if (value === undefined || value === null || value === '') continue;

    const normalized = String(value).trim().toLowerCase();

    if (normalized === 'publish' || normalized === 'published') {
      return 'publish';
    }

    if (normalized === 'draft') {
      return 'draft';
    }
  }

  return 'draft';
}

if (!isGlw) {
  return [
    {
      json: {
        ...input,
        source_mode: 'sheet',
        publishing_mode: normalizePublishingMode(
          input.publishing_mode,
          input.publishingMode,
          input.status
        ),
        job_id: '',
        callback_url: ''
      }
    }
  ];
}

const page = body.page || {};
const site = body.site || {};
const publishingSettings =
  body.publishingSettings &&
  typeof body.publishingSettings === 'object'
    ? body.publishingSettings
    : {};

const workflowContext =
  body.workflowContext &&
  typeof body.workflowContext === 'object'
    ? body.workflowContext
    : {};

const seoSettings =
  body.seoSettings &&
  typeof body.seoSettings === 'object'
    ? body.seoSettings
    : {};

const product = String(
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  page.category ||
  seoSettings.category ||
  ''
).trim();

const category = String(
  page.category ||
  seoSettings.category ||
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  ''
).trim();

const state = String(
  page.state ||
  workflowContext.state ||
  ''
).trim();

const city = String(
  page.city ||
  workflowContext.city ||
  ''
).trim();

const focusKeyword = String(
  page.primaryKeyword ||
  seoSettings.primaryKeyword ||
  ''
).trim();

const jobId = String(
  body.jobId ||
  body.job_id ||
  ''
).trim();

const callbackUrl = String(
  body.callbackUrl ||
  body.callback_url ||
  ''
).trim();

if (!jobId) {
  throw new Error('GLW request is missing jobId.');
}

if (!product) {
  throw new Error(
    'GLW request is missing page.product, page.productTopic, workflowContext.productTopic, or page.category.'
  );
}

if (!focusKeyword) {
  throw new Error(
    'GLW request is missing page.primaryKeyword or seoSettings.primaryKeyword.'
  );
}

if (site.id && site.id !== 'led-display-warehouse') {
  throw new Error(`Unsupported GLW site: ${site.id}`);
}

const productSlug = slugify(
  page.productSlug ||
  page.targetSlug ||
  seoSettings.targetSlug ||
  product
);

const stateSlug = slugify(
  page.stateSlug ||
  state
);

const citySlug = slugify(
  page.citySlug ||
  seoSettings.citySlug ||
  seoSettings.city_slug ||
  workflowContext.citySlug ||
  city
);

const hierarchicalSlug = String(
  page.hierarchicalSlug ||
  page.hierarchical_slug ||
  seoSettings.hierarchicalSlug ||
  workflowContext.hierarchicalSlug ||
  ''
).trim();

const slugParts = hierarchicalSlug
  ? hierarchicalSlug
      .split('/')
      .map((part) => slugify(part))
      .filter(Boolean)
  : [productSlug, stateSlug, citySlug].filter(Boolean);

const requestedTitle = String(
  page.pageTitle ||
  page.page_title ||
  page.title ||
  ''
).trim();

const requestedH1 = String(
  page.h1 ||
  ''
).trim();

const wordCount = Number(
  publishingSettings.wordCount ||
  page.wordCount ||
  page.word_count ||
  1500
);

const additionalInstructions = String(
  page.additionalInstructions ||
  page.additional_instructions ||
  workflowContext.additionalInstructions ||
  workflowContext.additional_instructions ||
  ''
).trim();

const publishingMode = normalizePublishingMode(
  body.publishing_mode,
  body.publishingMode,
  publishingSettings.status,
  page.publishingMode,
  page.publishing_mode,
  page.status
);

return [
  {
    json: {
      source_mode: 'glw',
      job_id: jobId,
      callback_url: callbackUrl,

      publishing_mode: publishingMode,

      site_id: site.id || 'led-display-warehouse',
      site_name: site.name || 'LED Display Warehouse',

      page_type: String(
        page.page_type ||
        page.pageType ||
        workflowContext.pageType ||
        product
      ).trim(),

      category,
      state,
      city,
      focus_keyword: focusKeyword,

      slug: slugParts.join('/'),

      page_title: requestedTitle,
      h1: requestedH1,

      internal_links: '',

      word_count:
        Number.isFinite(wordCount) && wordCount > 0
          ? wordCount
          : 1500,

      additional_instructions: additionalInstructions,

      status: 'Ready',
      row_number: ''
    }
  }
];

const response = $input.first().json;
const source = $('Prepare State Parent').first().json;

const statusCode = Number(response.statusCode || response.status || 0);
const body = response.body;

if (!Number.isFinite(statusCode) || statusCode < 200 || statusCode >= 300) {
  return [{
    json: {
      ...source,
      city_lookup_failed: true,
      city_page_found: false,
      existing_city_page_id: 0,
      existing_city_page_url: '',
      existing_city_page_status: '',
      existing_city_page_slug: source.city_slug || '',
      valid: false,
      validation_error_code: 'CITY_LOOKUP_FAILED',
      validation_error_message: `City lookup failed with status ${statusCode || 'UNKNOWN'} for slug=${source.city_slug || ''} parent=${source.state_parent_id || ''}.`,
      validation_error_node: 'Find Existing City Page'
    }
  }];
}

let list = [];
if (Array.isArray(body)) {
  list = body;
} else if (Array.isArray(response.data)) {
  list = response.data;
} else if (Array.isArray(response)) {
  list = response;
} else if (body && typeof body === 'object' && body.id) {
  list = [body];
} else if (response && typeof response === 'object' && response.id) {
  list = [response];
}

const cityPage = list.find((p) => p && p.id) || {};
const id = Number(cityPage.id || 0);

return [{
  json: {
    ...source,
    city_lookup_failed: false,
    city_page_found: id > 0,
    existing_city_page_id: id,
    existing_city_page_url: cityPage.link || '',
    existing_city_page_status: cityPage.status || '',
    existing_city_page_slug: cityPage.slug || source.city_slug || ''
  }
}];

const page = $input.first().json;
const source = $('Prepare State Parent').first().json;
const lookup = $('Normalize City Lookup Result').first().json;

const pageId = Number(page.id || lookup.existing_city_page_id || 0);
if (!pageId) {
  throw new Error('Missing city page ID after create/update branch.');
}

const pageUrl = String(page.link || lookup.existing_city_page_url || '');
const pageStatus = String(page.status || source.publishing_mode || 'draft').toLowerCase() === 'publish' ? 'publish' : 'draft';
const requestedMode = String(source.publishing_mode || 'draft').toLowerCase() === 'publish' ? 'publish' : 'draft';
const disposition = lookup.city_page_found ? 'UPDATED' : 'CREATED';

return [{
  json: {
    ...source,
    ...lookup,
    normalized_city_page_id: pageId,
    normalized_city_page_url: pageUrl,
    normalized_city_page_status: pageStatus,
    requested_publishing_mode: requestedMode,
    disposition
  }
}];

const normalized = $('Normalize Published City Page').first().json;
const source = $('Prepare State Parent').first().json;
const pageSource = $('Code in JavaScript').first().json;
const pageResponse = $('Fetch QA Page Snapshot').first().json || {};
const stateResponse = $('Fetch QA State Snapshot').first().json || {};
const mediaResponse = $('Fetch QA Featured Media').first().json || {};
const duplicateResponse = $('QA Duplicate Lookup').first().json || {};

function responseStatus(response) {
  return Number(response.statusCode || response.status || 0);
}

function responseBody(response) {
  return response && typeof response === 'object' && response.body !== undefined ? response.body : response;
}

function stripTags(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function decodeText(value) {
  return String(value || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#039;/gi, "'")
    .trim();
}

function normalizeSlug(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/^\/+|\/+$/g, '');
}

function extractPathFromUrl(value) {
  try {
    const url = new URL(String(value || ''));
    return normalizeSlug(url.pathname);
  } catch {
    return '';
  }
}

function countWords(value) {
  const text = stripTags(value);
  return text ? text.split(/\s+/).filter(Boolean).length : 0;
}

function findYoastMetaContent(meta, key, prop = 'name') {
  if (!Array.isArray(meta)) {
    return '';
  }
  const match = meta.find((entry) => entry && typeof entry === 'object' && String(entry[prop] || '').toLowerCase() === key.toLowerCase());
  return match && typeof match.content === 'string' ? match.content.trim() : '';
}

function getFocusKeyword(page, sourceData) {
  const pageMeta = page && typeof page.meta === 'object' && page.meta !== null ? page.meta : {};
  const direct = typeof pageMeta._yoast_wpseo_focuskw === 'string' ? pageMeta._yoast_wpseo_focuskw.trim() : '';
  if (direct) {
    return direct;
  }
  const sourceKeyword = String(sourceData.focus_keyphrase || sourceData.primary_keyword || pageSource.focus_keyphrase || pageSource.primaryKeyword || '').trim();
  return sourceKeyword;
}

function getRenderedTitle(page) {
  if (page && page.title && typeof page.title === 'object') {
    return decodeText(page.title.rendered || page.title.raw || '');
  }
  return '';
}

function findHeroImageAttributes(html) {
  const heroMatch = String(html || '').match(/<figure[^>]*page-hero-image[^>]*>[\s\S]*?<img[^>]*alt=["']([^"']*)["'][^>]*src=["']([^"']+)["'][^>]*>|<figure[^>]*page-hero-image[^>]*>[\s\S]*?<img[^>]*src=["']([^"']+)["'][^>]*alt=["']([^"']*)["'][^>]*>/i);
  if (heroMatch) {
    const alt = heroMatch[1] || heroMatch[4] || '';
    const src = heroMatch[2] || heroMatch[3] || '';
    return { alt: decodeText(alt), src: String(src || '').trim(), found: true };
  }

  const imgMatch = String(html || '').match(/<img[^>]*alt=["']([^"']*)["'][^>]*src=["']([^"']+)["'][^>]*>|<img[^>]*src=["']([^"']+)["'][^>]*alt=["']([^"']*)["'][^>]*>/i);
  if (imgMatch) {
    const alt = imgMatch[1] || imgMatch[4] || '';
    const src = imgMatch[2] || imgMatch[3] || '';
    return { alt: decodeText(alt), src: String(src || '').trim(), found: true };
  }

  return { alt: '', src: '', found: false };
}

function countInternalLinks(html) {
  const links = [];
  const regex = /href=["']([^"']+)["']/gi;
  let match;
  while ((match = regex.exec(String(html || ''))) !== null) {
    const href = String(match[1] || '').trim();
    if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) {
      continue;
    }
    if (href.startsWith('/')) {
      links.push(href);
      continue;
    }
    try {
      const url = new URL(href);
      if (url.hostname.toLowerCase() === 'leddisplaywarehouse.com') {
        links.push(href);
      }
    } catch {
      // ignore malformed links
    }
  }
  return links.length;
}

function hasPlaceholder(text) {
  const patterns = [
    /lorem ipsum/i,
    /\bTODO\b/i,
    /coming soon/i,
    /image placeholder/i,
    /\btest\b/i,
    /\bsample\b/i,
    /\{\{/,
    /\}\}/,
  ];
  return patterns.some((pattern) => pattern.test(String(text || '')));
}

const checks = {
  pageExists: 'UNKNOWN',
  hierarchy: 'UNKNOWN',
  slug: 'UNKNOWN',
  title: 'UNKNOWN',
  h1: 'UNKNOWN',
  body: 'UNKNOWN',
  featuredImage: 'UNKNOWN',
  heroImage: 'UNKNOWN',
  seo: 'UNKNOWN',
  internalLinks: 'UNKNOWN',
  imageAlt: 'UNKNOWN',
  duplicateCheck: 'UNKNOWN',
};
const failureReasons = {};

const pageStatus = responseStatus(pageResponse);
const stateStatus = responseStatus(stateResponse);
const mediaStatus = responseStatus(mediaResponse);
const duplicateStatus = responseStatus(duplicateResponse);
const page = responseBody(pageResponse) || {};
const statePage = responseBody(stateResponse) || {};
const media = responseBody(mediaResponse) || {};
const duplicateListRaw = responseBody(duplicateResponse);
const duplicateList = Array.isArray(duplicateListRaw) ? duplicateListRaw : [];

const pageId = Number(page.id || normalized.normalized_city_page_id || 0);
const pageUrl = String(page.link || normalized.normalized_city_page_url || '').trim();
const featuredImageUrl = String(media.source_url || $('Upload Image to WordPress').first().json.guid?.rendered || '').trim();
const renderedTitle = getRenderedTitle(page) || String(pageSource.page_title || '').trim();
const renderedContent = String(page.content && typeof page.content === 'object' ? page.content.rendered || page.content.raw || '' : '').trim();
const bodyText = stripTags(renderedContent);
const desiredHierarchicalSlug = normalizeSlug(source.desired_hierarchical_slug || pageSource.desired_hierarchical_slug || '');
const effectiveHierarchicalSlug = normalizeSlug([
  source.product_slug || '',
  source.state_slug || '',
  page.slug || source.city_slug || '',
].filter(Boolean).join('/'));
const h1Matches = String(renderedContent).match(/<h1\b[^>]*>[\s\S]*?<\/h1>/gi) || [];
const h1Text = h1Matches.length === 1 ? stripTags(h1Matches[0]) : '';
const heroImage = findHeroImageAttributes(renderedContent);
const internalLinkCount = countInternalLinks(renderedContent);
const metaTitle = String(page.yoast_title || page.yoast_head_json?.title || pageSource.seo_title || '').trim();
const metaDescription = findYoastMetaContent(page.yoast_meta, 'description') || String(page.yoast_head_json?.description || pageSource.meta_description || '').trim();
const focusKeyword = getFocusKeyword(page, source);
const stateParentId = Number(source.state_parent_id || 0);
const expectedProductParentId = Number(source.product_parent_id || 0);
const stateActualParentId = Number(statePage.parent || 0);
const forceQaFail = /QA_FORCE_FAIL/i.test(String(source.additional_instructions || pageSource.additional_instructions || pageSource.page_title || ''));

checks.pageExists = pageStatus >= 200 && pageStatus < 300 && pageId > 0 && pageUrl ? 'PASS' : 'FAIL';
if (checks.pageExists === 'FAIL') {
  failureReasons.pageExists = 'Missing published page snapshot. status=' + (pageStatus || 'UNKNOWN') + ' pageId=' + (pageId || 0) + ' url=' + (pageUrl || 'MISSING') + '.';
}

checks.hierarchy = checks.pageExists === 'PASS' && page.parent === stateParentId && stateStatus >= 200 && stateStatus < 300 && stateActualParentId === expectedProductParentId ? 'PASS' : 'FAIL';
if (checks.hierarchy === 'FAIL') {
  failureReasons.hierarchy = 'Hierarchy mismatch. cityParent=' + (page.parent || 0) + ' expectedState=' + stateParentId + '; stateParent=' + stateActualParentId + ' expectedProduct=' + expectedProductParentId + '.';
}

checks.slug = effectiveHierarchicalSlug && desiredHierarchicalSlug && effectiveHierarchicalSlug === desiredHierarchicalSlug ? 'PASS' : 'FAIL';
if (checks.slug === 'FAIL') {
  failureReasons.slug = 'Effective hierarchical slug ' + (effectiveHierarchicalSlug || 'MISSING') + ' does not match expected ' + (desiredHierarchicalSlug || 'MISSING') + '.';
}

checks.title = renderedTitle.length > 10 && !hasPlaceholder(renderedTitle) ? 'PASS' : 'FAIL';
if (checks.title === 'FAIL') {
  failureReasons.title = 'Title invalid. length=' + renderedTitle.length + '. placeholder=' + hasPlaceholder(renderedTitle) + '.';
}

checks.h1 = h1Matches.length === 1 && h1Text.length > 0 && !hasPlaceholder(h1Text) ? 'PASS' : 'FAIL';
if (checks.h1 === 'FAIL') {
  failureReasons.h1 = 'H1 invalid. count=' + h1Matches.length + ' textLength=' + h1Text.length + ' placeholder=' + hasPlaceholder(h1Text) + '.';
}

checks.body = countWords(bodyText) >= 1200 && !hasPlaceholder(renderedContent) && !hasPlaceholder(bodyText) ? 'PASS' : 'FAIL';
if (checks.body === 'FAIL') {
  failureReasons.body = 'Body invalid. wordCount=' + countWords(bodyText) + ' placeholder=' + (hasPlaceholder(renderedContent) || hasPlaceholder(bodyText)) + '.';
}

checks.featuredImage = Number(page.featured_media || 0) > 0 && mediaStatus >= 200 && mediaStatus < 300 && Number(media.id || 0) > 0 ? 'PASS' : 'FAIL';
if (checks.featuredImage === 'FAIL') {
  failureReasons.featuredImage = 'Featured media missing. featured_media=' + (page.featured_media || 0) + ' mediaStatus=' + (mediaStatus || 'UNKNOWN') + ' mediaId=' + (media.id || 0) + '.';
}

checks.heroImage = heroImage.found ? 'PASS' : 'FAIL';
if (checks.heroImage === 'FAIL') {
  failureReasons.heroImage = 'No hero image found inside rendered page content.';
}

checks.seo = metaTitle.length > 0 && metaDescription.length > 0 && String(focusKeyword || '').trim().length > 0 ? 'PASS' : 'FAIL';
if (checks.seo === 'FAIL') {
  failureReasons.seo = 'SEO fields missing. metaTitle=' + (metaTitle ? 'yes' : 'no') + ' metaDescription=' + (metaDescription ? 'yes' : 'no') + ' focusKeyword=' + (focusKeyword ? 'yes' : 'no') + '.';
}

checks.internalLinks = internalLinkCount >= 3 ? 'PASS' : 'FAIL';
if (checks.internalLinks === 'FAIL') {
  failureReasons.internalLinks = 'Expected at least 3 internal links but found ' + internalLinkCount + '.';
}

checks.imageAlt = heroImage.found && heroImage.alt.length > 0 && !hasPlaceholder(heroImage.alt) ? 'PASS' : 'FAIL';
if (checks.imageAlt === 'FAIL') {
  failureReasons.imageAlt = 'Hero image ALT invalid. present=' + heroImage.found + ' altLength=' + heroImage.alt.length + ' placeholder=' + hasPlaceholder(heroImage.alt) + '.';
}

checks.duplicateCheck = duplicateStatus >= 200 && duplicateStatus < 300 && duplicateList.length === 1 && Number(duplicateList[0]?.id || 0) === pageId ? 'PASS' : 'FAIL';
if (checks.duplicateCheck === 'FAIL') {
  const duplicateIds = duplicateList.map((entry) => Number(entry?.id || 0)).filter((id) => id > 0);
  failureReasons.duplicateCheck = 'Duplicate lookup mismatch. status=' + (duplicateStatus || 'UNKNOWN') + ' ids=' + (duplicateIds.join(',') || 'NONE') + ' expected=' + (pageId || 0) + '.';
}

if (forceQaFail) {
  checks.body = 'FAIL';
  failureReasons.body = 'Forced QA failure requested by input token QA_FORCE_FAIL.';
}

const qaFailed = Object.values(checks).some((value) => value === 'FAIL');
const failureSummary = qaFailed
  ? Object.entries(failureReasons).map(([key, value]) => key + ': ' + value).join(' | ')
  : '';
const qaChecksJson = JSON.stringify(checks);
const qaFailureReasonsJson = JSON.stringify(failureReasons);
const sheetNotes = qaFailed
  ? 'QA FAILED. ' + failureSummary + ' qaChecks=' + qaChecksJson + ' qaFailureReasons=' + qaFailureReasonsJson
  : 'Page published automatically. Hero image inserted below H1. Media title, alt text, and description applied. Caption intentionally left blank. QA PASS. qaChecks=' + qaChecksJson;

return [{
  json: {
    ...source,
    ...normalized,
    qa_gate_passed: !qaFailed,
    qa_callback_status: qaFailed ? 'FAILED_QA' : 'COMPLETE',
    qa_disposition: qaFailed ? 'FAILED_QA' : (normalized.disposition || 'UPDATED'),
    qa_wordpress_status: qaFailed ? 'qa_failed' : (normalized.normalized_city_page_status || 'draft'),
    qa_checks: checks,
    qa_failure_reasons: failureReasons,
    qa_failure_summary: failureSummary || 'Pre-publish QA gate failed.',
    qa_checks_json: qaChecksJson,
    qa_failure_reasons_json: qaFailureReasonsJson,
    qa_title: renderedTitle || String(pageSource.page_title || source.page_title || '').trim(),
    qa_page_id: pageId,
    qa_wordpress_url: pageUrl,
    qa_featured_image_url: featuredImageUrl,
    qa_meta_title: metaTitle,
    qa_meta_description: metaDescription,
    qa_focus_keyword: focusKeyword,
    sheet_status: qaFailed ? 'QA Failed' : 'Published',
    sheet_published_date: qaFailed ? '' : new Date().toISOString(),
    sheet_notes: sheetNotes,
  }
}];
